# KidsHealth Medical Information
import requests

KIDSHEALTH_API_KEY = "e02f0f27daadca306a80f17b2007f4ae900b8f0e"
BASE_URL = "https://api.kidshealth.org/v1"

def get_child_health_info(topic, age_range):
    """Get child health information"""
    response = requests.get(
        f"{BASE_URL}/topics",
        params={
            "topic": topic,
            "age": age_range,
            "api_key": KIDSHEALTH_API_KEY
        }
    )
    return response.json()
